from bloomerp.automation.flows.if_condition import IfConditionExecutor
from bloomerp.automation.results import RouteResult
from bloomerp.tests.base import (
    BloomerpWorkflowNodeTestCase,
    WorkflowNodeScenario,
)


class TestIfConditionNode(BloomerpWorkflowNodeTestCase):
    node_id = 'IF_CONDITION'
    executor_class = IfConditionExecutor

    def test_condition_ports_allow_fanout(self):
        ports = {port.id: port for port in self.executor_class.get_output_ports()}

        self.assertIsNone(ports["true"].max_connections)
        self.assertIsNone(ports["false"].max_connections)

    def get_simulations(self) -> list[WorkflowNodeScenario]:
        return [
            self.condition("equals", "age", "exact", "20", {"age": 20}, "true"),
            self.condition("does not equal", "age", "exact", "99", {"age": 20}, "false"),
            self.condition("greater than", "age", "greater_than", "18", {"age": 20}, "true"),
            self.condition("less than", "age", "less_than", "30", {"age": 25}, "true"),
            self.condition(
                "greater than or equal",
                "age",
                "greater_than_or_equal",
                "18",
                {"age": 18},
                "true",
            ),
            self.condition(
                "less than or equal",
                "age",
                "less_than_or_equal",
                "30",
                {"age": 30},
                "true",
            ),
            self.condition(
                "numeric comparison rejects non-numeric values",
                "name",
                "greater_than",
                "Alice",
                {"name": "Bob"},
                "false",
            ),
            self.condition(
                "numeric comparison accepts mixed float and integer values",
                "age",
                "greater_than",
                75.5,
                {"age": 80},
                "true",
            ),
            self.condition(
                "an extracted queryset count can be compared",
                "input",
                "greater_than",
                "0",
                1,
                "true",
            ),
        ]

    @staticmethod
    def condition(name, field, operator, value, trigger_data, expected_port):
        return WorkflowNodeScenario(
            name=name,
            parameters={"field": field, "operator": operator, "value": value},
            trigger_data=trigger_data,
            expected_output=RouteResult(
                port_id=expected_port,
                output=trigger_data,
            ),
        )
